enum ReaderHTML {
static let page = #"""
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kokoro Reader</title>
<style>
:root{color-scheme:dark;--bg:#0b0d0d;--panel:#151918;--line:#2a3230;--muted:#929c96;--text:#f0f3ee;--lime:#c8f36a}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 72% -20%,#29351d 0,transparent 42%),var(--bg);color:var(--text);font:15px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
main{max-width:1120px;margin:auto;padding:32px 34px 26px}.top{display:flex;justify-content:space-between;align-items:center;padding-bottom:20px;border-bottom:1px solid var(--line)}.brand{font-size:13px;font-weight:800;letter-spacing:.22em}.brand b{color:var(--lime)}.micro{font-size:10px;letter-spacing:.16em;color:var(--muted)}
h1{font-size:58px;line-height:.98;letter-spacing:-.06em;margin:36px 0 10px;font-weight:680}.intro{color:var(--muted);margin:0 0 28px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:16px}.panel{background:linear-gradient(145deg,#181e1b,#111514);border:1px solid var(--line);border-radius:15px;padding:18px}.label{display:block;color:var(--muted);font-size:10px;letter-spacing:.17em;text-transform:uppercase;margin-bottom:11px}
textarea{width:100%;height:360px;resize:vertical;background:#0b0f0e;border:1px solid #303a35;border-radius:9px;padding:17px;color:var(--text);font:16px/1.75 Georgia,serif;outline:none}textarea:focus,select:focus{border-color:var(--lime)}.row{display:flex;gap:9px;align-items:center;flex-wrap:wrap;margin-top:13px}button{border:0;border-radius:8px;padding:11px 16px;font-weight:700;cursor:pointer;background:var(--lime);color:#12170a}button.alt{background:#242c28;color:var(--text);border:1px solid #39433e}button:disabled{opacity:.45;cursor:default}select{width:100%;padding:11px;border:1px solid #35403a;border-radius:8px;background:#0c100e;color:var(--text)}
.side{display:flex;flex-direction:column;gap:13px}.status{font-size:12px;color:var(--muted);min-height:35px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#626d66;margin-right:8px}.dot.on{background:var(--lime);box-shadow:0 0 10px #c8f36a}.note{font-size:11px;color:#87918b;line-height:1.6}.big{font-size:29px;letter-spacing:-.05em}.big small{font-size:11px;color:var(--muted);letter-spacing:0}.progress{height:3px;background:#2a332e;border-radius:4px;margin-top:13px;overflow:hidden}.bar{height:100%;width:0;background:var(--lime);transition:width .2s}audio{width:100%;margin-top:14px}.footer{display:flex;justify-content:space-between;margin-top:22px;padding-top:15px;border-top:1px solid var(--line);font-size:10px;letter-spacing:.12em;color:#737e77}
@media(max-width:760px){main{padding:22px 16px}.layout{grid-template-columns:1fr}.side{display:grid;grid-template-columns:1fr 1fr}h1{font-size:48px}textarea{height:280px}}
</style></head><body><main><header class="top"><div class="brand">KOKORO <b>/</b> READER</div><div class="micro">PRIVATE AUDIO · ON-DEVICE SPEECH</div></header>
<h1>Read it.<br>Hear it.</h1><p class="intro">A quiet, focused reader for essays, articles and long documents.</p>
<div class="layout"><section class="panel"><label class="label" for="essay">Your text</label><textarea id="essay" placeholder="Paste an essay, article or chapter here…"></textarea><div class="row"><button id="play">Generate &amp; play</button><button id="stop" class="alt" disabled>Stop</button><button id="clear" class="alt">Clear</button></div><div class="progress"><div class="bar" id="bar"></div></div><audio id="audio" controls hidden></audio></section>
<aside class="side"><div class="panel"><label class="label" for="voice">Voice</label><select id="voice"><option value="bf_emma">Emma · British female</option><option value="bm_george">George · British male</option><option value="bf_isabella">Isabella · British female</option><option value="bm_lewis">Lewis · British male</option><option value="af_heart">Heart · American female</option><option value="am_michael">Michael · American male</option></select></div>
<div class="panel"><label class="label">Speech engine</label><div class="big">82M <small>parameters</small></div><p class="note">Kokoro-82M · compact open model</p></div><div class="panel"><label class="label">Status</label><div class="status" id="status"><span class="dot"></span>Ready when you are</div><p class="note">Your text is processed on this Mac. The model downloads once and is cached for later use.</p></div><div class="panel"><label class="label">First launch</label><p class="note">An internet connection is needed to download the speech engine and voice data. No account or Hugging Face website visit is required.</p></div></aside></div>
<footer class="footer"><span>KOKORO READER · COMMUNITY PROJECT</span><span>FREE · OPEN SOURCE</span></footer></main>
<script type="module">
const $=id=>document.getElementById(id);let engine=null,stopFlag=false,urls=[];
const status=(s,on=false)=>{$('status').innerHTML='<span class="dot '+(on?'on':'')+'"></span>'+s};
function splitText(s,max=420){const sentences=s.replace(/\\s+/g,' ').match(/[^.!?]+[.!?]+|[^.!?]+$/g)||[s];let out=[],cur='';for(const x of sentences){const v=x.trim();if(!v)continue;if((cur+' '+v).trim().length>max&&cur){out.push(cur);cur=v}else cur=(cur+' '+v).trim()}if(cur)out.push(cur);return out}
async function load(){if(engine)return engine;status('Loading speech engine…',true);const {KokoroTTS}=await import('https://esm.sh/kokoro-js@1.2.1?bundle');engine=await KokoroTTS.from_pretrained('onnx-community/Kokoro-82M-v1.0-ONNX',{dtype:'q8',device:'wasm',progress_callback:p=>{if(p.status==='progress'&&p.progress!=null)status('Downloading model · '+Math.round(p.progress)+'%',true)}});return engine}
$('play').onclick=async()=>{const text=$('essay').value.trim();if(!text){status('Paste some text first.');return}$('play').disabled=true;$('stop').disabled=false;$('audio').hidden=true;stopFlag=false;urls.forEach(URL.revokeObjectURL);urls=[];try{const t=await load(),parts=splitText(text),blobs=[];for(let i=0;i<parts.length;i++){if(stopFlag)break;status('Generating section '+(i+1)+' of '+parts.length,true);$('bar').style.width=(i/parts.length*100)+'%';const result=await t.generate(parts[i],{voice:$('voice').value});blobs.push(result.toBlob())}if(stopFlag){status('Stopped.');return}if(!blobs.length)return;urls=blobs.map(b=>URL.createObjectURL(b));let n=0,a=$('audio');a.hidden=false;a.onended=()=>{n++;if(n<urls.length){a.src=urls[n];a.play()}else{status('Finished.');$('bar').style.width='100%'}};a.src=urls[0];await a.play();status('Playing · '+parts.length+' sections',true)}catch(e){console.error(e);status('Could not start the speech engine. Check your connection and try again.')}finally{$('play').disabled=false;$('stop').disabled=true}};
$('stop').onclick=()=>{stopFlag=true;$('audio').pause();status('Stopping…')};$('clear').onclick=()=>{$('essay').value='';$('audio').pause();$('audio').hidden=true;$('bar').style.width='0';status('Ready when you are')};
</script></body></html>
"""#
}
